ANALYSIS_SCHEMA = '''Return ONLY valid JSON with this shape: {"class_summary":"", "mastery_score":0, "strengths":[{"concept":"","evidence":""}], "misconceptions":[{"name":"","description":"","student_count":0,"example_evidence":"","severity":"high|medium|low","recommended_response":""}], "students_needing_support":[{"student":"","issue":""}], "students_showing_mastery":[], "recommended_focus_for_tomorrow":[], "differentiated_support":{"needs_reteaching":{"students":[],"teacher_action":"","activity":""},"developing":{"students":[],"teacher_action":"","activity":""},"ready_to_extend":{"students":[],"teacher_action":"","activity":""}}}'''
def analysis_prompt(lesson, questions, responses):
    return f"You are a respectful teaching assistant. Analyze only supplied evidence. Never infer intelligence, diagnoses, disabilities, or unsupported traits. Identify patterns. {ANALYSIS_SCHEMA}\nLESSON: {lesson}\nQUESTIONS: {questions}\nRESPONSES: {responses}"
def improvement_prompt(lesson, analysis, plan):
    schema = '{"overall_recommendation":"", "keep":[], "change":[{"original":"","suggestion":"","reason":""}], "add":[{"activity":"","duration_minutes":0,"reason":""}], "remove_or_shorten":[{"activity":"","reason":""}], "revised_plan":[{"duration":"","activity":"","purpose":""}]}'
    return f"You are a practical teaching assistant. Make small actionable changes while preserving appropriate parts of the plan. Base every reason on the analysis. Return ONLY valid JSON shaped {schema}. OBJECTIVE: {lesson}\nANALYSIS: {analysis}\nCURRENT PLAN: {plan}"
